#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_.\/:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function int(field, text, least) {
  if (!INT.test(text) || BigInt(text) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

function makeBucket(name, capacity, refill, per) {
  return {
    name,
    state() {
      return { units: capacity * per, last: null }
    },
    advance(s, tick) {
      if (s.last !== null) {
        s.units += refill * (tick - s.last)
        if (s.units > capacity * per) s.units = capacity * per
      }
      s.last = tick
    },
    allows: (s) => s.units >= per,
    record(s) { s.units -= per },
  }
}

function makeWindow(name, limit, span) {
  return {
    name,
    state: () => ({ ticks: [] }),
    advance(s, tick) {
      s.ticks = s.ticks.filter((t) => t > tick - span)
    },
    allows: (s) => BigInt(s.ticks.length) < limit,
    record(s, tick) { s.ticks.push(tick) },
  }
}

function run(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const states = new Map()
  const stats = new Map()
  const out = []
  let started = false
  let prev = null
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const f = line.split(/\s+/)
    try {
      const word = f[0]
      if (['bucket', 'window', 'route'].includes(word) && started) {
        throw new Fail('declarations must come before the first event')
      }
      if (word === 'bucket' || word === 'window') {
        const isB = word === 'bucket'
        if (f.length !== (isB ? 5 : 4)) {
          throw new Fail(isB ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
        }
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        let p
        if (isB) {
          const c = int('capacity', f[2], 1)
          const r = int('refill', f[3], 0)
          const per = int('per', f[4], 1)
          if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
          p = makeBucket(f[1], c, r, per)
        } else {
          const l = int('limit', f[2], 0)
          const s = int('span', f[3], 1)
          if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
          p = makeWindow(f[1], l, s)
        }
        policies.set(f[1], p)
      } else if (word === 'route') {
        if (f.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!NAME.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
        for (const n of f.slice(2)) {
          if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
        }
        if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
        routes.set(f[1], f.slice(2).map((n) => policies.get(n)))
      } else if (word === 'event') {
        if (f.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = int('tick', f[1], 0)
        const key = f[2]
        if (!NAME.test(key)) throw new Fail(`invalid key ${key}`)
        if (prev !== null && tick < prev) throw new Fail(`tick ${tick} is before tick ${prev}`)
        started = true
        prev = tick
        let best = null
        for (const pre of routes.keys()) {
          if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
        }
        let denier = null
        if (best !== null) {
          const ps = routes.get(best)
          const ss = ps.map((p) => {
            const k = p.name + '\0' + key
            if (!states.has(k)) states.set(k, p.state())
            return states.get(k)
          })
          ps.forEach((p, j) => p.advance(ss[j], tick))
          for (let j = 0; j < ps.length; j++) {
            if (!ps[j].allows(ss[j])) { denier = ps[j].name; break }
          }
          if (denier === null) ps.forEach((p, j) => p.record(ss[j], tick))
        }
        const st = stats.get(key) ?? { a: 0, d: 0 }
        stats.set(key, st)
        if (denier === null) st.a++
        else st.d++
        out.push(denier === null ? `${tick} ${key} allow` : `${tick} ${key} deny ${denier}`)
      } else {
        throw new Fail(`unknown directive ${word}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  if (mode === 'replay') return out
  const res = []
  let ta = 0
  let td = 0
  for (const k of [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
    const s = stats.get(k)
    ta += s.a
    td += s.d
    res.push(`${k} allowed=${s.a} denied=${s.d}`)
  }
  res.push(`total allowed=${ta} denied=${td}`)
  return res
}

try {
  const lines = run(readFileSync(0, 'utf8'))
  process.stdout.write(lines.map((l) => l + '\n').join(''))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
EOF
