        throw new Fail(`unknown directive ${word}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  if (mode === 'replay') return out
  const res = []
  let ta = 0
  let td = 0
  for (const k of [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
    const s = stats.get(k)
    ta += s.a
    td += s.d
    res.push(`${k} allowed=${s.a} denied=${s.d}`)
  }
  res.push(`total allowed=${ta} denied=${td}`)
  return res
}

